; diag.asm -- chapter 22: two lines drawn with vaddr
; generated by gen22.py
        INCLUDE "msx.inc"
        OUTPUT "diag.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Two lines, x = y and x = y + 64, for y = 0 to 191: for each pixel vaddr
; finds its byte, and the byte gets the pixel's bit. One pixel a byte, so no
; byte is read back (chapter 25 draws over what is there).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld c, 0                 ; y
line:   ld b, c                 ; x = y
        call pixel
        ld a, c
        add a, 64
        ld b, a                 ; x = y + 64
        call pixel
        inc c
        ld a, c
        cp 192
        jr nz, line
        VDP_REG 1, $C0          ; the display on
done:   jr done

; pixel: B = x, C = y: the byte of pixel (x, y) set to that pixel alone
pixel:  call vaddr
v1:     ld a, l                 ; the write address
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, b
        and 7
        ld e, a
        ld d, 0
        ld hl, bit
        add hl, de
        ld a, (hl)              ; $80 >> (x AND 7)
        out (VDP_DATA), a
        ret
bit:    db $80, $40, $20, $10, $08, $04, $02, $01

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third; add $2000 for its colours. Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
